import{_ as r,o as s,c as a,a2 as p}from"./chunks/framework.BXzK3EA4.js";const n="/assets/%E8%A3%B8%E6%9C%BA%E4%BA%91%E6%B4%BB%E5%8A%A8.B_nVPKBM.png",o="/assets/%E9%80%89%E6%8B%A9%E8%A3%B8%E6%9C%BA%E4%BA%9111.avmkXH1I.png",e="/assets/%E7%AB%8B%E5%8D%B3%E8%B4%AD%E4%B9%B0%E8%A3%B8%E6%9C%BA%E4%BA%91%E6%9C%8D%E5%8A%A1%E5%99%A8.CkfHghtF.png",i="/assets/%E8%B4%AD%E4%B9%B0%E5%AE%98%E7%BD%91%E6%8E%A8%E8%8D%90%E7%9A%84%E8%A3%B8%E6%9C%BA%E4%BA%91.CNWGg-bI.png",l="/assets/%E7%AB%8B%E5%8D%B3%E8%B4%AD%E4%B9%B0%E6%8E%A8%E8%8D%90%E9%85%8D%E7%BD%AE11.DajwyMXE.png",g="/assets/%E8%B4%AD%E4%B9%B0%E8%A3%B8%E6%9C%BA%E4%BA%91%E6%8E%A8%E8%8D%90%E4%BA%A7%E5%93%81.DDjB6Ayg.png",E="/assets/%E7%99%BB%E5%BD%95.C2il1sQf.png",d="/assets/%E8%A3%B8%E6%9C%BA%E4%BA%91%E6%8E%A7%E5%88%B6%E5%8F%B011.GtaZFUis.png",B="/assets/%E6%8E%A7%E5%88%B6%E5%8F%B0%E8%B4%AD%E4%B9%B0%E4%B8%AD%E5%BF%8311.XbgiVEGj.png",c="/assets/%E8%B4%AD%E4%B9%B0%E8%A3%B8%E6%9C%BA%E4%BA%91%E9%80%89%E6%8B%A9%E5%9C%B0%E5%8C%BA.pc4i4ruJ.png",A="/assets/%E8%A3%B8%E6%9C%BA%E4%BA%91%E8%B4%AD%E7%89%A9%E8%BD%A6%E9%85%8D%E7%BD%AE.DCfzQXRe.png",m="/assets/%E7%AB%8B%E5%8D%B3%E8%B4%AD%E4%B9%B0%E8%A3%B8%E6%9C%BA%E4%BA%91.T8A91m1d.png",h="/assets/%E7%A1%AE%E8%AE%A4%E4%BA%A7%E5%93%81%E4%BF%A1%E6%81%AF.BM4Q8bc8.png",_="/assets/%E7%BB%93%E8%B4%A611.mdYYJ8yY.png",b="/assets/%E4%BB%98%E6%AC%BE%E5%AE%8C%E6%88%9011.Dr5L_lxN.png",u="/assets/%E6%9C%89%E6%95%88%E7%9A%84bare._sT8jwWI.png",x=JSON.parse('{"title":"购买裸机云","description":"","frontmatter":{"title":"购买裸机云"},"headers":[],"relativePath":"baremetal/quickstart/purchase.md","filePath":"baremetal/quickstart/purchase.md","lastUpdated":1794292918000}'),D={name:"baremetal/quickstart/purchase.md"};function P(k,t,C,f,I,S){return s(),a("div",null,[...t[0]||(t[0]=[p('<p>本文介绍如何通过 RakSmart 官网产品入口和控制台入口购买裸机云服务器。</p><hr><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h3><ol><li><p>注册 RakSmart 账号，详细步骤可参考<a href="/beginners-guide/register-account/">注册 RakSmart 账号</a>。</p></li><li><p>了解 Raksmart 产品和配置项、计费周期、付款方式等信息，参考<a href="/beginners-guide/buy-products/purchase.html">购买 RakSmart 产品</a>。</p></li></ol><hr><h3 id="通过官网产品入口购买" tabindex="-1">通过官网产品入口购买 <a class="header-anchor" href="#通过官网产品入口购买" aria-label="Permalink to &quot;通过官网产品入口购买&quot;">​</a></h3><p>您可以直接通过 RakSmart 官网产品入口购买推荐的裸机云服务器。</p><ol><li><p>使用注册的 RakSmart 账号登录 <a href="https://cn.raksmart.com/" target="_blank" rel="noreferrer">RakSmart 官网</a>。</p></li><li><p>将鼠标悬停在顶部导航<strong>裸机云</strong>，打开下拉列表。</p><p><img src="'+n+'" alt="裸机云活动.png"></p></li><li><p>选择一个裸机云产品类型，进入产品页面。</p><p><img src="'+o+'" alt="选择裸机云11.png"></p></li><li><p>单击<strong>立即订购</strong>。</p><p><img src="'+e+'" alt="立即购买裸机云服务器.png"></p></li><li><p>在产品清单页面，选择购买裸机云服务器的地区、配置，单击<strong>现在订购</strong>。</p><p><img src="'+i+'" alt="购买官网推荐的裸机云.png"></p></li><li><p>在<strong>配置</strong> - <strong>购物</strong>车页面，参考如下信息完成自定义产品配置。各配置项详细说明，请参考<a href="#配置项及付款流程说明">配置项及付款流程说明</a>。</p><p><img src="'+l+'" alt="立即购买推荐配置11.png"></p></li><li><p>（可选）您也可以在上述 <strong>裸机云的产品页面</strong>，选择一个推荐产品配置，单击<strong>立即购买</strong>。</p><p><img src="'+g+'" alt="购买裸机云推荐产品.png"></p></li></ol><hr><h3 id="通过控制台入口购买" tabindex="-1">通过控制台入口购买 <a class="header-anchor" href="#通过控制台入口购买" aria-label="Permalink to &quot;通过控制台入口购买&quot;">​</a></h3><p>本文主要介绍通过 RakSmart 控制台购买中心入口购买裸机云服务器。</p><ol><li><p>使用注册的 RakSmart 账号登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 官网</a>。</p><p><img src="'+E+'" alt="登录.png"></p></li><li><p>在官网顶部导航右侧，单击<strong>控制台</strong>，进入控制台客户中心页面。</p><p><img src="'+d+'" alt="裸机云控制台11.png"></p></li><li><p>单击<strong>购买中心</strong>，进入<strong>购物车</strong>页面。</p><p><img src="'+B+'" alt="控制台购买中心11.png"></p></li><li><p>单击<strong>裸机云</strong>，参考如下信息选择地区、分类、核心数等配置。</p><p><img src="'+c+'" alt="购买裸机云选择地区.png"></p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>地区</td><td>裸机云服务器部署的可用区。目前支持的区域和可用区有美洲的硅谷、洛杉矶、西雅图，亚洲的香港、台湾、东京等区和欧洲的法兰克福。关于区域和可用区的详细介绍可参考 区域和可用区。</td></tr><tr><td>分类</td><td>裸机云服务器的功能和配置类型，主要包括按如下分类：标配机型：基础标准配置，满足常规业务，如网站部署、轻量应用运行的基础算力与资源需求；站群多 IP：配备更多独立 IP，适配多网站、多域名并行部署的业务场景；大带宽：提供高带宽资源，适配视频流媒体、数据传输等高网络吞吐需求的业务；高防：集成抗攻击防护能力，适配易受网络攻击的业务（如电商平台、游戏服务器）。</td></tr><tr><td>核心数</td><td>裸机云服务器的核心配置选项， 支持通过核心数选择单 CPU / 双 CPU；也支持通过 Gold、Platinum 和 AMD 等 CPU 型号选择。</td></tr></tbody></table></li><li><p>选择产品类型，单击<strong>立即订购</strong>，进入<strong>配置</strong> - <strong>购物车</strong>页面。各配置项详细说明，请参考<a href="#配置项及付款流程说明">配置项及付款流程说明</a>。</p><p><img src="'+A+'" alt="裸机云购物车配置.png"></p></li></ol><hr><h3 id="配置项及付款流程说明" tabindex="-1">配置项及付款流程说明 <a class="header-anchor" href="#配置项及付款流程说明" aria-label="Permalink to &quot;配置项及付款流程说明&quot;">​</a></h3><ol><li><p>配置选项设置</p><p>请参考如下信息完成配置选项填写。</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>处理器</td><td>指裸机云服务器的 CPU 型号，如“E5-2620”，决定了服务器的计算能力，是支撑业务运行、处理请求的核心硬件。</td></tr><tr><td>内存</td><td>指裸机云服务器的内存容量。用于临时存储运行中的程序与数据，容量越大，可同时承载的服务和并发请求越多。</td></tr><tr><td>系统盘</td><td>用于安装操作系统及核心运行环境的磁盘，是服务器启动和运行的基础存储介质。</td></tr><tr><td>数据盘1</td><td>额外挂载的独立存储磁盘，可用于存放业务数据、日志、文件等，与系统盘分离可避免系统故障影响数据，也能按需扩容。</td></tr><tr><td>数据盘2</td><td>同数据盘1。</td></tr><tr><td>带宽类型</td><td>服务器接入的公网线路类型，包含大陆优化 VIP、精品 CN2 和国际 BGP，分别针对中国访问优化、跨境访问等不同场景。</td></tr><tr><td>带宽</td><td>网络线路在单位时间内能够传输的数据总量。带宽数值越大表示传输能力越强，即在单位时间内传输的数据量越多。</td></tr><tr><td>流量</td><td>服务器公网传输的数据总量限制，如“大陆优化 VIP 100M 不限”，“不限”表示不限制月度流量，适合大流量业务场景。</td></tr><tr><td>IP数量</td><td>分配给服务器的公网 IP 地址数量，支持单 IP 或多 IP 配置。</td></tr><tr><td>高防IP</td><td>具备 DDoS 攻击防护能力的公网 IP，可过滤恶意流量，保障服务器在遭受网络攻击时仍能正常对外提供服务。</td></tr><tr><td>站群IP</td><td>一组独立的公网 IP 地址，适合搭建多站点业务，可避免单 IP 风险，提升多站点的搜索引擎友好度。</td></tr><tr><td>镜像类型</td><td>包含了裸机云服务器所需的基本操作系统、应用数据的特殊文件：操作系统——服务器管理硬件资源和运行应用的软件平台的系统环境，可选类型包括 Linux 系统（CentOS、 Ubuntu、Debian、Rocky、Almalinux）、Windows 系统（Windows Server Datacenter 版本）；应用镜像——操作系统 + 应用（例如宝塔） + 运行环境。</td></tr><tr><td>登录方式</td><td>支持密码登录及更安全的密钥登录。</td></tr><tr><td>控制台密码</td><td>用于登录裸机云服务器系统的密码。</td></tr></tbody></table></li><li><p>选择附加信息</p><p>根据您的业务需求，选择是否开启自动续费的开关。若开启系统将自动从您的账户余额扣款续费；否则到期后服务将暂停。</p></li><li><p>选择付款周期</p><p>选择服务的购买时长，支持月付、季度付、半年付和年付。</p></li><li><p>选择数量</p><p>选择购买服务器的数量。</p></li><li><p>完成配置填写后，在右侧订购总额区域单击<strong>立即购买</strong>。</p><p><img src="'+m+'" alt="立即购买裸机云.png"></p></li><li><p>在<strong>确认产品信息</strong>页面支持选择优惠券（若有），根据需要输入<strong>订单备注</strong>信息；确认没有问题后，勾选<strong>我已阅读并同意</strong>服务条款，单击<strong>结算</strong>。</p><p><img src="'+h+'" alt="确认产品信息.png"></p></li><li><p>在<strong>支付</strong>页面，选择某一种付款方式支付或者使用余额支付。</p><p><img src="'+_+'" alt="结账11.png"></p></li><li><p>支付完成后如下图所示。</p><p><img src="'+b+'" alt="付款完成11.png"></p></li></ol><hr><h3 id="操作结果" tabindex="-1">操作结果 <a class="header-anchor" href="#操作结果" aria-label="Permalink to &quot;操作结果&quot;">​</a></h3><ol><li><p>在控制台左侧导航<strong>产品管理</strong>区域单击<strong>裸机云</strong>，进入<strong>我的产品与服务</strong>页面。此页面支持通过<strong>地区</strong>或<strong>状态</strong>筛选，或通过搜索框查找目标服务器信息。</p><p><img src="'+u+'" alt="有效的bare.png"></p></li><li><p>当服务器的状态由<strong>审核中</strong>变为<strong>有效的</strong>时，即证明此服务器已开通。</p></li></ol><hr><h3 id="后续步骤" tabindex="-1">后续步骤 <a class="header-anchor" href="#后续步骤" aria-label="Permalink to &quot;后续步骤&quot;">​</a></h3><p>购买并开通裸机云服务器后，您可以开始使用。详细内容请参见<a href="./login.html">登录裸机云</a>。</p>',21)])])}const R=r(D,[["render",P]]);export{x as __pageData,R as default};
